entries[422648] = { ["name"] = "Dunkelflammenspitzhacke", ["text"] = "200 Meter Reichweite\nSofort\nDer Kerzenkönig bereitet eine übergroße Spitzhacke vor, um sie auf ein Ziel zu wuchten. Die Spitzhacke prallt auf das erste von ihr getroffene Ziel, fügt ihm 29 körperlichen Schaden zu und stößt es zurück. Erwischt sie stattdessen eine Wachsstatue, wird diese dadurch zerschmettert." }
entries[422649] = { ["name"] = "Versengendes Schlitzen", ["text"] = "300 Meter Reichweite\nSofort\nGlimmeron schlitzt sein aktuelles Ziel auf und verursacht 6 Sek. lang alle 5.2 Sek. 120 körperlichen Schaden und 0 Feuerschaden.\n\nWenn ' [DNT] Scorching Slash ' abläuft, explodiert das aktuelle Ziel und fügt allen Spielercharakteren 100 Feuerschaden zu. Spielercharaktere, die weiter von der Explosion entfernt sind, erleiden geringeren Schaden.\n\nNach Ablauf erleidet das aktuelle Ziel außerdem 20 Sek. lang 500% mehr Schaden durch ' [DNT] Scorching Slash '." }
