entries[422691] = { ["name"] = "Lavageysire", ["text"] = "Wirken in 2 sek.\nGlimmeron stampft auf den Boden und lässt bei zufälligen Spielercharakteren in der Nähe Lavaströme ausbrechen. Diese ' Lavageysire ' verursachen 507666 Feuerschaden und stoßen alle getroffenen Spielercharaktere zurück.\n\nWenn sich die Lava gesetzt hat, bleibt eine Lache von ' Schwelender Boden ' zurück." }
entries[422692] = { ["name"] = "Lichtsauger", ["text"] = "5 Meter Reichweite\nWirken in 1.5 sek.\nErstickt die Flamme einer Kerze und verringert ihre Energie 10 Sek. lang alle 1 Sek. um 2. Dabei erleiden alle Spielercharaktere innerhalb von 30 Metern jedes Mal 969780 Schattenschaden." }
entries[422693] = { ["name"] = "Sonnenflammen", ["text"] = "30 Meter Reichweite\nWirken in 2 sek. 3 sek. Abklingzeit\nLässt eine Säule aus Sonnenflammen niedergehen, die alle Gegner innerhalb von 8 verbrennt und ihnen zunächst 5 Feuerschaden und zusätzlich im Verlauf von 12 Sek. alle 3 Sek. 2 Feuerschaden zufügt." }
