entries[422832] = { ["name"] = "Um sich greifendes Lauffeuer" }
entries[422833] = { ["name"] = "Spreading Fire [ DNT]" }
entries[422836] = { ["name"] = "Brennende Schuppen", ["text"] = "Sofort\nFyrakk strahlt sengende Hitze ab, die allen Spielercharakteren alle 2 Sek. 101533 Schattenflammenschaden zufügt." }
entries[422837] = { ["name"] = "Apokalyptisches Brüllen", ["text"] = "Wirken in 4.8 sek.\nFyrakk entlässt ein entflammendes Gebrüll, fügt allen Spielercharakteren 1560347 Schattenflammenschaden zu und stößt sie weg.\n\nSpielercharaktere erleiden 12 Sek. lang alle 1 Sek. zusätzlich 101533 Schattenflammenschaden." }
entries[422838] = { ["name"] = "Legendäres Muster erlernen - Lederverarbeitung", ["text"] = "25 Meter Reichweite\nSofort\nLehrt den Spielercharakter, besondere Rezepte zu verwenden." }
entries[422839] = { ["name"] = "Apokalyptisches Brüllen", ["text"] = "300 Meter Reichweite\nSofort\nFyrakk entlässt ein entflammendes Gebrüll, fügt allen Spielercharakteren 1560347 Schattenflammenschaden zu und stößt sie weg.\n\nSpielercharaktere erleiden 12 Sek. lang alle 1 Sek. zusätzlich 101533 Schattenflammenschaden." }
entries[422840] = { ["name"] = "Gesundheitspilz", ["text"] = "100 Meter Reichweite\nSofort\nErhöht die maximale Gesundheit in einer Tiefe um 3%." }
entries[422842] = { ["name"] = "Meisterschaftspilz", ["text"] = "100 Meter Reichweite\nSofort\nErhöht die Meisterschaft in einer Tiefe um 3%." }
entries[422843] = { ["name"] = "Tempopilz", ["text"] = "100 Meter Reichweite\nSofort\nErhöht das Tempo in einer Tiefe um 3%." }
entries[422844] = { ["name"] = "Gegenstandsstufe", ["text"] = "Sofort" }
entries[422850] = { ["name"] = "Death Knight Blood 10.2 Class Set 2pc", ["text"] = "Beim Verbrauchen von Runenmacht besteht eine Chance, dass Euer nächster Einsatz von 'Herzstoß' das Ziel mit 'Aschenverfall' belegt, was 8 Sek. lang den Euch zugefügten Schaden um 10% verringert und Euren den betroffenen Zielen zugefügten Schaden um 20% erhöht." }
entries[422851] = { ["name"] = "Death Knight Blood 10.2 Class Set 4pc", ["text"] = "Der Hinrichtungsschaden von 'Seelenernter' und der Schaden von 'Monströse Gliedmaße' belegen gegnerische Ziele mit 'Aschenverfall', und der direkte Schaden von 'Herzstoß' und 'Siedendes Blut' verlängert 'Aschenverfall' um 1.0 Sek." }
entries[422852] = { ["name"] = "Death Knight Frost 10.2 Class Set 2pc", ["text"] = "Die Reichweite von 'Kettenunterkühlung' wird um 4 Meter erhöht und der Effekt kann von Euch abprallen. Jedes Mal, wenn 'Kettenunterkühlung' abprallt, wird Euer Schaden 12 Sek. lang um 4% erhöht. Bis zu 5-mal stapelbar." }
entries[422853] = { ["name"] = "Death Knight Frost 10.2 Class Set 4pc", ["text"] = "'Kettenunterkühlung' kann 3 weitere Male abprallen, und bei jedem Abprallen besteht eine Chance von 35%, dass Ihr eine Rune erhaltet, die entweder die Abklingzeit von 'Kettenunterkühlung' um 5 Sek. oder die Abklingzeit von 'Runenwaffe verstärken' um 6 Sek. verringert." }
entries[422854] = { ["name"] = "Death Knight Unholy 10.2 Class Set 2pc", ["text"] = "'Apokalypse' beschwört einen zusätzlichen Magus der Toten. Euer 'Schattenblitz' von 'Magus der Toten' verschießt jetzt eine Schattenblitzsalve auf bis zu 4 Gegner in der Nähe." }
entries[422855] = { ["name"] = "Death Knight Unholy 10.2 Class Set 4pc", ["text"] = "Das Verbrauchen einer Rune erhöht die Dauer Eurer aktiven Magi um 0.5 Sek. und Eure Magi wirken nun auch 'Schaden verstärken', wodurch Euer verursachter Schaden 10 Sek. lang um 5% erhöht wird." }
entries[422856] = { ["name"] = "Raureif" }
entries[422857] = { ["name"] = "Demon Hunter Havoc 10.2 Class Set 2pc", ["text"] = "'Klingentanz' löst automatisch 'Gleve werfen' auf Euer Primärziel aus und verursacht 100% des Schadens. Bei jedem Hieb besteht eine Chance von 50%, dem Gegner mit 'Gleve werfen' Schaden in Höhe von 35% zuzufügen." }
entries[422858] = { ["name"] = "Pips smaragdgrünes Freundschaftsabzeichen", ["text"] = "Ca. 2 Procs pro Minute\nSchließt Euch dem Traumteam an und erhaltet ( 266 / 12) von Pips Meisterschaft, Urctos' Vielseitigkeit oder Aerwynns kritischem Trefferwert, je nachdem, wer Euer derzeitiger bester Freund ist.\n\nEure Zauber und Fähigkeiten haben die Chance, einen zufälligen neuen besten Freund zu markieren, der Euch den entsprechenden passiven Bonus gewährt und diesen auf 266 erhöht, bevor er im Verlauf von 12 Sek. abnimmt.\n(12s Abklingzeit)" }
entries[422859] = { ["name"] = "Demon Hunter Havoc 10.2 Class Set 4pc", ["text"] = "'Gleve werfen' verringert die verbleibende Abklingzeit von 'Die Jagd' um 2.0 Sek., und der regelmäßige Schadenseffekt von 'Die Jagd' hält 6 Sek. länger an." }
entries[422860] = { ["name"] = "Demon Hunter Vengeance 10.2 Class Set 2pc", ["text"] = "Wenn Ihr ein Ziel angreift, das von 'Zeichen der Flamme' betroffen ist, werden 8 Sek. lang Euer Schaden und Eure Heilung um 2% und Eure Ausdauer um 2% erhöht. Bis zu 5-mal stapelbar.\n(750ms Abklingzeit)" }
entries[422861] = { ["name"] = "Demon Hunter Vengeance 10.2 Class Set 4pc", ["text"] = "Der regelmäßige Schaden von 'Zeichen der Flamme' hat eine Chance, aufzulodern, ein zusätzliches Seelenfragment vom Ziel abzuschlagen und (60.72% der Angriffskraft) Schaden zusätzlich zu verursachen. Pro 40 verbrauchtem Zorn verringert sich die Abklingzeit um 1.0 Sek." }
entries[422862] = { ["name"] = "Druid Balance 10.2 Class Set 2pc", ["text"] = "Wenn 'Finsternis' endet oder Ihr in den Kampf eingreift, geht Ihr in einen 'Traumzustand' über, wodurch die Zauberzeit Eurer nächsten Einsätze von 2 'Sternenfeuer' oder 'Zorn' um 40% verringert und der von ihnen verursachten Schaden um 100% erhöht wird." }
entries[422863] = { ["name"] = "Druid Balance 10.2 Class Set 4pc", ["text"] = "'Sternensog' oder 'Sternenregen' erhöhen den Arkan- oder Naturschadenbonus Eurer aktuellen 'Finsternis' um zusätzlich 2%, bis zu 10%." }
entries[422864] = { ["name"] = "Druid Guardian 10.2 Class Set 2pc", ["text"] = "Wut, die Ihr während 'Zorn des Schläfers' verbraucht, treibt das Wachstum von 'Traumdornen' an, die Euch schützen, nachdem 'Zorn des Schläfers' endet, und 25% des Euch zugefügten Schadens absorbieren, während die Dornen bestehen, bis zu (660 / 100 * Angriffskraft) pro 20 verbrauchter Wut." }
entries[422865] = { ["name"] = "Druid Guardian 10.2 Class Set 4pc", ["text"] = "Das Verbrauchen von 40 Wut, während 'Zorn des Schläfers' aktiv ist, verlängert dessen Dauer um 1.0 Sek., bis zu einem Maximum von 5.0 Sekunden. Eure 'Traumdornen' werden zu 'Lodernde Dornen', wodurch 100% des absorbierten Schadens auf den Angreifer zurückgeworfen werden." }
entries[422866] = { ["name"] = "Druid Restoration 10.2 Class Set 2pc", ["text"] = "Eure Fähigkeit 'Pflege' und die Eures Hainwächters heilen jetzt 2 zusätzliche Verbündete im Umkreis von 40 Metern mit einer Effektivität von 40%." }
entries[422867] = { ["name"] = "Druid Restoration 10.2 Class Set 4pc", ["text"] = "Wenn 'Freizaubern' verbraucht wird, löst 'Nachwachsen' jetzt auch 'Pflege' mit 200% Effektivität bei einem verletzten Verbündeten aus, wobei jene bevorzugt werden, die mit einem Eurer regelmäßigen Heileffekte belegt sind." }
entries[422868] = { ["name"] = "Evoker Augmentation 10.2 Class Set 2pc", ["text"] = "Jeder dritte Einsatz von dritte 'Voraussicht' hält 100% länger an." }
entries[422869] = { ["name"] = "Evoker Augmentation 10.2 Class Set 4pc", ["text"] = "Das Wirken von 'Voraussicht' verbessert Eure nächste 'Eruption' mit schmaleren Rissen für jede aktive 'Voraussicht', die jeweils (110% der Zaubermacht) Schaden verursachen und 'Schwarzmacht' um 0.2 Sek verlängern." }
entries[422870] = { ["name"] = "Ruferklassenset 10.2, Verheerung, 2 Teile", ["text"] = "Während 'Drachenwut' aktiv ist, erhaltet Ihr alle 6 Sek. 'Smaragdtrance', wodurch der von Euch verursachte Schaden um 5% erhöht wird. Bis zu 5-mal stapelbar.\n(Procchance: 15%, 500ms Abklingzeit)" }
entries[422871] = { ["name"] = "Ruferklassenset 10.2, Verheerung, 4 Teile", ["text"] = "Wenn 'Drachenwut' endet, dauert 'Smaragdtrance' 5 Sek. pro Stapel an und gewährt Euch alle 5 Sek. 'Essenzexplosion'." }
entries[422872] = { ["name"] = "Evoker Preservation 10.2 Class Set 2pc", ["text"] = "Ermächtigte Zauber wirken bis zu 3-mal 'Lebende Flamme' mit 50% Effektivität auf Gegner oder getroffene Verbündete." }
entries[422873] = { ["name"] = "Evoker Preservation 10.2 Class Set 4pc", ["text"] = "Beim Einsatz von 'Lebende Flamme' besteht eine Chance, 'Echo' mit 70% Effektivität auf geheilte Verbündete zu wirken oder auf einen Verbündeten in der Nähe, der noch nicht mit 'Echo' belegt ist.\n(Procchance: 33%)" }
entries[422874] = { ["name"] = "Hunter Beast Mastery 10.2 Class Set 2pc", ["text"] = "'Zorn des Wildtiers' beschwört ein Alphatier für 10 Sek.\n(1s Abklingzeit)" }
entries[422875] = { ["name"] = "Hunter Beast Mastery 10.2 Class Set 4pc", ["text"] = "Euer zuletzt beschworenes Alphatier gehorcht nun Eurem 'Tötungsbefehl' und kann von 'Raubtierhiebe' profitieren." }
entries[422876] = { ["name"] = "Hunter Marksmanship 10.2 Class Set 2pc", ["text"] = "'Schnellfeuer' lässt für 2 Sek. eine Salve auf die Position des Ziels herabregnen." }
entries[422877] = { ["name"] = "Hunter Marksmanship 10.2 Class Set 4pc", ["text"] = "'Erbstück von Haus Windläufer' hat nun eine Chance von 15%, einen 'Windpfeil' auf Ziele zu schießen, die von 'Salve' getroffen wurden.\n(Procchance: 15%)" }
entries[422878] = { ["name"] = "Hunter Survival 10.2 Class Set 2pc", ["text"] = "'Zorn des Adlers' erhöht Eure kritische Trefferchance und die Eures Tiers 12 Sek. lang um 15% und Euren verursachten kritischen Schaden um 15%." }
entries[422879] = { ["name"] = "Hunter Survival 10.2 Class Set 4pc", ["text"] = "'Zorn des Adlers' wirft eine kostenlose 'Lauffeuerbombe' mit einer Effektivität von 100% auf Euer aktuelles Ziel, löst bei Eurem nächsten Einsatz von 'Lauffeuerbombe' keine Abklingzeit aus und erhöht den Schaden, den 'Lauffeuerbombe' Eurem Primärziel zufügt, 12 Sek. lang um 40%." }
entries[422880] = { ["name"] = "Mage Arcane 10.2 Class Set 2pc", ["text"] = "Wenn 'Freizaubern' verbraucht wird, wird der Zauberschaden 20 Sek. lang um 2% erhöht. Bis zu einem Wert von 10% stapelbar." }
entries[422881] = { ["name"] = "Mage Arcane 10.2 Class Set 4pc", ["text"] = "Nachdem Ihr 3-mal 'Freizaubern' verbraucht habt, verbrauchen Eure nächsten Einsätze von 'Arkane Geschosse' 'Arkane Batterie', wodurch Ihr Eurem Primärziel 150% mehr Schaden zufügt und auf bis zu 4 Gegner in der Nähe schießt und ihnen 100% mehr Schaden zufügt." }
entries[422882] = { ["name"] = "Mage Fire 10.2 Class Set 2pc", ["text"] = "Bei kritischen Treffern durch 'Pyroschlag' und 'Flammenstoß' erhaltet Ihr 'Sengender Zorn', wodurch der kritische Schaden 12 Sek. lang um 4% erhöht wird. Bis zu einem Wert von 20% stapelbar." }
entries[422883] = { ["name"] = "Mage Fire 10.2 Class Set 4pc", ["text"] = "Bei Aktivierung von 'Einäschern' wird der Schadensbonus für kritische Treffer von 'Sengender Zorn' 12 Sek. lang um 150% erhöht." }
entries[422884] = { ["name"] = "Mage Frost 10.2 Class Set 2pc", ["text"] = "Der Schaden durch 'Gletscherstachel' wird um 16% erhöht. Wenn ein gefrorenes Ziel zerschmettert wird, erfolgt zudem eine Explosion, die Gegnern in der Nähe 15% des verursachten Schadens zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[422885] = { ["name"] = "Mage Frost 10.2 Class Set 4pc", ["text"] = "Beim Wirken von 'Gletscherstachel' besteht eine Chance von 40%, 'Hirnfrost' auszulösen." }
entries[422886] = { ["name"] = "Monk Brewmaster 10.2 Class Set 2pc", ["text"] = "'Feuerodem' verursacht 40% Bonusschaden als Schattenflammenschaden und sorgt dafür, dass Ihr um 50% Eures verursachten Feuerschadens geheilt werdet." }
entries[422887] = { ["name"] = "Monk Brewmaster 10.2 Class Set 4pc", ["text"] = "Eure Angriffe auf Ziele, die mit 'Feuerodem' belegt sind, haben eine Chance, 15% zusätzlichen Schaden als Schattenflammenschaden zu verursachen, und jedes Himmlische Gebräu gewährt außerdem einen gestaffelten Absorptionseffekt in Höhe von 100% des verursachten Schattenflammenschadens, durch den durch 'Staffelung' verzögerter Schaden stattdessen verhindert wird." }
entries[422889] = { ["name"] = "Monk Mistweaver 10.2 Class Set 2pc", ["text"] = "'Erneuernder Nebel' belegt sein Hauptziel mit 'Chiharmonie', wodurch dessen von Euch erhaltene Heilung 8 Sek. lang um 25% erhöht wird." }
entries[422890] = { ["name"] = "Monk Mistweaver 10.2 Class Set 4pc", ["text"] = "20% sämtlicher Heilung, die Ihr mit 'Chiharmonie' hervorgerufen habt, wird gespeichert und dann mit 'Erneuernder Nebel' gleichmäßig auf Eure Verbündeten übertragen, wenn 'Chiharmonie' ausläuft oder aufgefrischt wird." }
entries[422891] = { ["name"] = "Monk Windwalker 10.2 Class Set 2pc", ["text"] = "Ca. 2.5 Procs pro Minute\nKostenlose Einsätze von 'Wirbelnder Kranichtritt' gewähren 'Blackout-Verstärkung', sodass Euer nächster Einsatz von 'Blackout-Tritt' 250% mehr Schaden verursacht. Nahkampfangriffe haben eine Chance, 'Blackout-Verstärkung' zu gewähren." }
entries[422892] = { ["name"] = "Monk Windwalker 10.2 Class Set 4pc", ["text"] = "Die durch 'Blackout-Verstärkung' ermächtigten Einsätze von 'Blackout-Tritt' verringern die Abklingzeit von 'Furorfäuste', 'Tritt der aufgehenden Sonne', 'Schlag des Windlords' und 'Wirbelnder Drachenschlag' um 3.0 Sek.\nDer Schaden von 'Furorfäuste', 'Tritt der aufgehenden Sonne', 'Schlag des Windlords' und 'Wirbelnder Drachenschlag' ist um 4% erhöht." }
entries[422893] = { ["name"] = "Paladin Holy 10.2 Class Set 2pc", ["text"] = "Wenn 'Lichtschimmer' schwindet oder aufgefrischt wird, wird das Ziel mit 'Heiliger Nachhall' belegt, um im Verlauf von 8 Sek. einen Verbündeten um (108% der Zaubermacht) Gesundheit zu heilen oder einem Gegner (96% der Zaubermacht) Schaden zuzufügen. Es können sich mehrere Anwendungen von 'Heiliger Nachhall' überlappen, bis zu 6-mal." }
entries[422894] = { ["name"] = "Paladin Holy 10.2 Class Set 4pc", ["text"] = "'Tagesanbruch' beschleunigt das Tempo jetzt 6 Sek. lang um 25% und die Abklingzeit wird um 15 Sek. verringert.\n(250ms Abklingzeit)" }
entries[422895] = { ["name"] = "Paladin Protection 10.2 Class Set 2pc", ["text"] = "'Richturteil' gewährt einen Stapel 'Heiligung' und verringert den von Euch erlittenen Schaden um 2.0% pro Stapel. Bei 5 Stapeln wird Euer nächster Einsatz von 'Weihe' ermächtigt, wodurch Schaden und Heilung um 200% und der Radius um 30% erhöht werden. Die Stapel von 'Heiligung' werden zurückgesetzt, wenn die ermächtigte 'Weihe' endet." }
entries[422896] = { ["name"] = "Paladin Protection 10.2 Class Set 4pc", ["text"] = "Solange Ihr Euch in einer ermächtigten 'Weihe' befindet, haben Eure Fähigkeiten eine Chance, 40% Bonusschaden oder -heilung als Feuerschaden zu verursachen." }
entries[422899] = { ["name"] = "Priest Discipline 10.2 Class Set 2pc", ["text"] = "Der Schaden von 'Heilige Pein' und 'Sühne' ist um 20% erhöht und 'Heilige Pein' verlängert die Dauer einer aktiven 'Abbitte' um 2.0 Sek." }
entries[422900] = { ["name"] = "Priest Discipline 10.2 Class Set 4pc", ["text"] = "'Heilige Pein' hat während 'Schattenbündnis' eine Chance von 100%, ein weiteres Mal gewirkt zu werden und (80% der Zaubermacht) Schattenschaden zu verursachen." }
entries[422901] = { ["name"] = "Priest Holy 10.2 Class Set 2pc", ["text"] = "'Segenswort: Epiphanie' belegt Ziele 18 Sek. lang mit 'Erneuerung'. 'Segenswort: Heiligung' belegt Verbündete, die durch diesen Zauber geheilt werden, 6 Sek. lang mit 'Erneuerung'." }
entries[422902] = { ["name"] = "Priest Holy 10.2 Class Set 4pc", ["text"] = "Die Heilung durch 'Erneuerung' beinhaltet eine Chance, dass der nächste Einsatz von 'Segenswort: Heiligung' oder 'Segenswort: Epiphanie' keine Aufladung verbraucht und 50% weniger Mana kostet. Kann bis zu 2 Aufladungen akkumulieren." }
entries[422903] = { ["name"] = "Priest Shadow 10.2 Class Set 2pc", ["text"] = "'Schattenwort: Tod' wird 2 weitere Male mit einer Effektivität von 15% ausgelöst. Wird zusätzlich 1 weiteres Mal mit 15% Effektivität ausgelöst, wenn der Todessprecher aktiv oder die Gesundheit Eures Ziels geringer als (85% der Zaubermacht) % ist." }
entries[422904] = { ["name"] = "Priest Shadow 10.2 Class Set 4pc", ["text"] = "Jedes Mal, wenn Ihr Schaden durch 'Schattenwort: Tod' erleidet, erhaltet Ihr einen Stapel von 'Todesqual', was den Initialschaden Eures nächsten Einsatzes von 'Schattenwort: Schmerz' um 225% oder den Schaden Eures nächsten Einsatzes von 'Schattengeschoss' um 50% erhöht. Bis zu 12-mal stapelbar." }
entries[422905] = { ["name"] = "Rogue Assassination 10.2 Class Set 2pc", ["text"] = "Das Verbrauchen von 10 Energie gewährt Euch 'Natürliche Kraft', wodurch 6 Sek. lang Euer Angriffstempo um 1.0% und Euer Naturschaden um 1.0% erhöht wird. Mehrere Instanzen von 'Natürliche Kraft' können sich überlappen, bis zu einem Maximum von 12 Instanzen." }
entries[422906] = { ["name"] = "Rogue Assassination 10.2 Class Set 4pc", ["text"] = "'Vergiften' ermächtigt sich selbst, was eine 'Vergiftende Explosion' auslöst, die allen Gegnern in der Nähe (90% der Angriffskraft) Naturschaden zufügt, während 'Vergiften' aktiv ist. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Wenn 'Vergiftende Explosion' einem Einzelziel Schaden zufügt, wird dieser um 30% erhöht." }
entries[422907] = { ["name"] = "Rogue Outlaw 10.2 Class Set 2pc", ["text"] = "'Finsterer Stoß' hat eine zusätzliche Chance von 10%, ein weiteres Mal zuzuschlagen." }
entries[422908] = { ["name"] = "Rogue Outlaw 10.2 Class Set 4pc", ["text"] = "'Schicksalswürfel' erneuert zusätzlich einen zufälligen Kampfbonus von 'Schicksalswürfel', den Ihr bereits besitzt." }
entries[422909] = { ["name"] = "Rogue Subtlety 10.2 Class Set 4pc", ["text"] = "Eure Schattenklone verursachen 20% mehr Schaden mit allen Angriffen und verleihen Euch bei Beschwörung 2 Combopunkte pro Klon." }
entries[422910] = { ["name"] = "Rogue Subtlety 10.2 Class Set 2pc", ["text"] = "'Ausweiden', 'Blutung' oder 'Schwarzpulver' haben eine Chance, einen Schattenklon zu beschwören, der Euren Finishing-Move kopiert und 70% zusätzlichen Schattenschaden verursacht." }
entries[422911] = { ["name"] = "Shaman Elemental 10.2 Class Set 2pc", ["text"] = "'Urzeitliche Welle' wirkt zusätzlich einen 'Elementarschlag' mit 70% Effektivität auf das Ziel und gewährt Euch 10.0 Sek. lang alle drei Bonuseffekte von 'Elementarschlag'." }
entries[422912] = { ["name"] = "Shaman Elemental 10.2 Class Set 4pc", ["text"] = "'Lavaeruption' verbrennt Euer Ziel und fügt ihm im Verlauf von 4 Sek. 10% zusätzlichen Schaden zu. Nach Verbrauchen von 'Urzeitliche Welle' treffen außerdem Eure nächsten 2 Einsätze von 'Lavaeruption' bis zu 3 zusätzliche Ziele, die von Eurem 'Flammenschock' betroffen sind, und fügen ihnen 65% des normalen Schadens zu." }
entries[422913] = { ["name"] = "Shaman Enhancement 10.2 Class Set 2pc", ["text"] = "'Urzeitliche Welle' beschwört einen Blitzwildgeist, der den von Euch verursachten Naturschaden 15 Sek. lang um 20% erhöht." }
entries[422914] = { ["name"] = "Shaman Enhancement 10.2 Class Set 4pc", ["text"] = "Das Beschwören eines Wildgeistes verringert die Abklingzeit von 'Urzeitliche Welle' um 7.0 Sek." }
entries[422915] = { ["name"] = "Shaman Restoration 10.2 Class Set 2pc", ["text"] = "'Kettenheilung', 'Heilende Woge' und 'Welle der Heilung' markieren ihr Hauptziel mit einem 'Gezeitenreservoir', wodurch es 15 Sek. lang 15% Eurer durch 'Springflut' verursachten Heilung erhält." }
entries[422916] = { ["name"] = "Shaman Restoration 10.2 Class Set 4pc", ["text"] = "Die Heilung von 'Springflut' ist um 25% erhöht. Wenn 'Springflut' auf demselben Ziel wie 'Gezeitenreservoir' aktiv ist, hat der regelmäßige Heileffekt von 'Springflut' eine um 6% erhöhte Chance, eine neue 'Springflut' auf einem Verbündeten in der Nähe auszulösen." }
entries[422917] = { ["name"] = "Warlock Affliction 10.2 Class Set 2pc", ["text"] = "'Seelenfäule' verursacht 15% mehr Schaden und hält 4 Sek. länger an." }
entries[422918] = { ["name"] = "Warlock Affliction 10.2 Class Set 4pc", ["text"] = "'Seelenfäule' gewährt 3 'Umbralfeuerzunder', der den Schaden Eures nächsten Einsatzes von 'Unheilvolle Euphorie' um 50% oder Eures nächsten Einsatzes von 'Saat der Verderbnis' um 60% erhöht. Außerdem bewirkt 'Umbralfeuerzunder', dass 'Unheilvolle Euphorie' die Dauer Eurer regelmäßigen Schadenseffekte und von 'Heimsuchung' um 2 Sek. verlängert." }
entries[422919] = { ["name"] = "Warlock Demonology 10.2 Class Set 2pc", ["text"] = "Wenn ein 'Dämonischer Kern' verschlungen wird, verursacht dies einen 'Verdammnisbrand', der nach 20 Sek. explodiert und Gegnern in der Nähe (268.747% der Zaubermacht) Schattenschaden oder einem einzigen Gegner [(268.747% der Zaubermacht) * (2.25)] Schattenschaden zufügt. 'Hand von Gul'dan' verringert die Dauer Eurer aktiven Verdammnisbrände um 1 Sek. pro verbrauchtem Seelensplitter." }
entries[422920] = { ["name"] = "Warlock Demonology 10.2 Class Set 4pc", ["text"] = "Wenn 'Verdammnisbrand' entfernt wird, besteht eine Chance, einen Schreckensdämon zu beschwören, der 5-mal 'Verdammnisblitzsalve' wirkt, bevor er wieder verschwindet. Jede 'Verdammnisblitzsalve' fügt bis zu 4 Gegnern [(1.553369999\n* (Zaubermacht) * 1 * (1 + Vielseitigkeit)) * 1.169617819] Schattenschaden oder einem einzigen Gegner [((1.553369999\n* (Zaubermacht) * 1 * (1 + Vielseitigkeit)) * 1.169617819) * (2.1)] Schattenschaden zu." }
entries[422921] = { ["name"] = "Warlock Destruction 10.2 Class Set 2pc", ["text"] = "Blitze von 'Dimensionsriss' verursachen jetzt 25% des Schadens, der Gegnern in der Nähe zugefügt wurde. Der regelmäßige Schaden von 'Feuerbrand' hat eine Chance, eine Aufladung von 'Dimensionsriss' zu gewähren." }
entries[422922] = { ["name"] = "Warlock Destruction 10.2 Class Set 4pc", ["text"] = "'Dimensionsriss' kann jetzt einen mächtigen 'Flammenriss' beschwören, der 20-mal 'Sengender Blitz' verschießt, was dem Ziel (56.9622% der Zaubermacht) Feuerschaden und zusätzlich (22.793% der Zaubermacht) Feuerschaden im Verlauf von 10 Sek. zufügt." }
entries[422923] = { ["name"] = "Warrior Arms 10.2 Class Set 2pc", ["text"] = "Ca. 2 Procs pro Minute\n'Verwunden' verursacht 30% mehr Schaden und der Blutungsschaden von 'Verwunden' hat eine Chance, 'Plötzlicher Tod' auszulösen." }
entries[422924] = { ["name"] = "Warrior Arms 10.2 Class Set 4pc", ["text"] = "Plötzlicher Tod' sorgt dafür, dass Ihr bei Eurem nächsten Einsatz von 'Hinrichten' stark auf den Boden schlagt und dabei einen 'Donnerknall' erzeugt, der um 200% erhöhten Schaden verursacht. Außerdem blutet das Ziel von 'Hinrichten' und erleidet im Verlauf von 5 Sek. 50% des Schadens von 'Hinrichten'. Wenn die Blutung erneut angewendet wird, wird der verbleibende Schaden der neuen Blutung hinzugefügt.\n(500ms Abklingzeit)" }
entries[422925] = { ["name"] = "Warrior Fury 10.2 Class Set 2pc", ["text"] = "'Odyns Zorn' verursacht 50% mehr Schaden und lässt Eure nächsten 3 Einsätze von 'Blutdurst' 150% zusätzlichen Schaden verursachen, bei einer um 100% erhöhten kritischen Trefferchance gegen das Primärziel." }
entries[422926] = { ["name"] = "Warrior Fury 10.2 Class Set 4pc", ["text"] = "Die kritischen Treffer von 'Blutdurst' reduzieren die Abklingzeit von 'Odyns Zorn' um 2.5 Sek.\n(500ms Abklingzeit)" }
entries[422927] = { ["name"] = "Warrior Protection 10.2 Class Set 2pc", ["text"] = "Beim Verbrauchen von Wut besteht eine Chance, Euren nächsten Einsatz von 'Schildschlag' Eure auf dem Ziel aktiven Blutungseffekte verbrauchen zu lassen, was sofort 40% des verbleibenden Schadens Eurer Fähigkeiten 'Tiefe Wunden' und 'Verwunden' und 100% des verbleibenden Schadens von 'Donnerndes Gebrüll' verursacht und den von Euch erlittenen Schaden 5 Sek. lang um 10% verringert." }
entries[422928] = { ["name"] = "Warrior Protection 10.2 Class Set 4pc", ["text"] = "Für jeden verbrauchten Blutungseffekt auf dem Ziel wird der von Euch erlittene Schaden um weitere 2% verringert. Wenn 'Schildschlag' eine Blutung verbraucht, wird die Abklingzeit von 'Donnerknall' abgeschlossen und die Abklingzeit von 'Donnerndes Gebrüll' um 3.0 Sek. verringert." }
