entries[422935] = { ["name"] = "Ewiger Feuersturm", ["text"] = "Sofort\nFyrakk verdunkelt den Himmel permanent und lässt regelmäßig brennende Meteore auf Spielercharaktere herabregnen. Jeder Meteor fügt Spielercharakteren innerhalb von 5 Metern um den Einschlagsort 398880 Schattenflammenschaden zu und es entsteht ein ' Wirbelnder Feuersturm '.\n\nDie Splitter der Meteore treffen auch Amirdrassil und fügen Spielercharakteren innerhalb von 4 Metern um die Einschlagsorte 725237 Schattenflammenschaden zu." }
