entries[423051] = { ["name"] = "Brennendes Licht", ["text"] = "Wirken in 3 sek.\nBraunspyß entfesselt einen Stoß heiligen Lichts, der allen Spielercharakteren 4848899 Heiligschaden sowie 12 Sek. lang alle 2 Sek. 4848899 zusätzlichen Heiligschaden zufügt. Der Lichtstoß heilt Braunspyß zudem um 10% seiner maximalen Gesundheit.\n\nWährend Ermächtigung durch ' Rachsüchtige Wut ' ist die Zauberzeit von ' Brennendes Licht ' verringert." }
entries[423052] = { ["name"] = "Segen der Feuerlande", ["text"] = "Unbegrenzte Reichweite\nSofort\nDurch Verzehr des Tranks verwandelt sich der Zaubernde in einen Lavaschleim und wird befriedet, außerdem wird seine Bewegungsgeschwindigkeit um 80% verringert. Gewährt Immunität gegen die Feuer auf der Brücke von Lunedane.\n\nAngriffe beenden den Effekt." }
