entries[423115] = { ["name"] = "Lichtspeer", ["text"] = "200 Meter Reichweite\nSofort\nOdyn erschafft einen Lichtspeer am Aufenthaltsort eines Spielercharakters, der allen Spielercharakteren innerhalb von 8 Metern 13334472 Heiligschaden zufügt sowie allen anderen Spielercharakteren 1939560 Heiligschaden.\n\nZusätzlich fügt jeder Speer allen Spielercharakteren in der Nähe alle 2 Sek. 3751205 Heiligschaden zu." }
