entries[423120] = { ["name"] = "Provozierendes Brüllen", ["text"] = "30 Meter Reichweite\nSofort 3 sek. Abklingzeit\nFurorion brüllt und bringt alle Gegner in einem Radius von 8 Metern dazu, ihn anzugreifen. Hat keine Wirkung auf Ziele, die ihn bereits angreifen." }
entries[423121] = { ["name"] = "Hammer der Reinheit", ["text"] = "Unbegrenzte Reichweite\nSofort\nBraunspyß ruft sengendes Licht auf die Position eines Spielercharakters herab und fügt Spielercharakteren innerhalb von 3 Metern 7272815 Heiligschaden zu. Die Hämmer drehen sich dann spiralförmig vom Einschlagsort aus nach außen und fügen Spielercharakteren auf ihrem Weg 7272815 Heiligschaden zu.\n\nWährend Ermächtigung durch ' Rachsüchtige Wut ' trifft ' Hammer der Reinheit ' 5 Spielercharaktere." }
entries[423123] = { ["name"] = "Geschwindigkeit" }
entries[423124] = { ["name"] = "Weissagung der Urflamme", ["text"] = "Ca. 1.5 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine geringe Chance, Euch für 20 Sek. 'Vernichtende Flamme' zu gewähren, wodurch Eure kritischen Treffer zusätzlich 50% Feuerschaden verursachen, der auf Gegner in der Nähe aufgeteilt wird. Die Flamme kann insgesamt [ 4682 * (1 + Vielseitigkeit)] Schaden verursachen, bevor sie erlischt, was durch kritische Treffer weiter erhöht werden kann.\n\nSchaden und Maximalwert erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5 Gegnern." }
entries[423125] = { ["name"] = "Lauffeuerexplosion" }
entries[423126] = { ["name"] = "Merithra" }
entries[423131] = { ["name"] = "Kauterisieren", ["text"] = "50 Meter Reichweite\nWirken in 1 sek. 5 sek. Abklingzeit\nKauterisiert die Wunden eines Verbündeten, was 5 Sek. lang alle 1 Sek. 10% seiner Gesundheit wiederherstellt." }
