entries[423136] = { ["name"] = "Plötzliches Ableben", ["text"] = "Erhöht den Blutungsschaden um 15%.\n\nZiele mit weniger als 35% Gesundheit bluten sofort aus und erleiden tödlichen Schaden, wenn der übrige Blutungsschaden, den Ihr ihnen zufügen würdet, mehr als 150% ihrer verbleibenden Gesundheit beträgt." }
