entries[423145] = { ["name"] = "Nullemporstoßen", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Leerensteinmonstrosität schmettert auf die Plattform, verursacht 3151784 Schattenschaden und löst eine Reihe an Explosionen aus, die Spielercharakteren innerhalb von 7 Metern um jeden Einschlag 9697798 Schattenschaden zufügen\n\nZusätzlich werden dadurch Leerensteinfragmente in der Arena verschossen." }
