entries[423148] = { ["name"] = "Schlängelnde Flammen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchlangengleiche Flammen umgeben den Spielercharakter, fügen ihm 4 Feuerschaden zu und strahlen 12 Sek. lang alle 1 Sek. ' Wirbelndes Sengen ' auf Spielercharaktere in der Nähe aus. Die Flammen verdichten sich mit der Zeit, was ihren Effektbereich verkleinert und ihren Schaden erhöht.\nBeim Ablauf wird eine ' Windende Eruption ' ausgelöst." }
entries[423149] = { ["name"] = "Einsturz", ["text"] = "100 Meter Reichweite\nSofort\nDer Sturmangriff des alten Wachsbarts erschüttert die Höhle und lässt nach einer kurzen Verzögerung über jedem Spielercharakter Felsbrocken fallen. Felsbrocken verursachen innerhalb von 4 Metern 6061123 Naturschaden.\n\nTödlich für Schuftknechte und Schuftmägde." }
