entries[423417] = { ["name"] = "Brennender Wirbelwind", ["text"] = "30 Meter Reichweite\nSofort\nGreift Gegner in der Nähe mit einem Wirbelwind aus gleißendem Stahl an und fügt allen Gegnern innerhalb von 4 Metern 6 Sek. lang alle 1 Sek. 5 Feuerschaden zu." }
entries[423418] = { ["name"] = "Erblühen von Amirdrassil", ["text"] = "Die Heilung eines Verbündeten unter 80% Gesundheit gewährt ihm 'Erblühen von Amirdrassil', was ihn im Verlauf von 6 Sek. um ( 1025 * 6) Gesundheit heilt. Dieser Effekt kann einmal pro Minute auftreten.\n\nWenn das Ziel bei Ablauf dieses Effekts über 95% Gesundheit geheilt wurde, breitet sich das Erblühen auf 3 verletzte Verbündete aus und heilt sie im Verlauf von 6 Sek. um ( 513 * 6) Gesundheit. Wenn das Ziel nicht vollständig geheilt ist, blüht das Erblühen auf und absorbiert stattdessen 9226 Schaden.\n(1Min. Abklingzeit)" }
