entries[423557] = { ["name"] = "Instabile Fragmente", ["text"] = "50 Meter Reichweite\nSofort\nWenn Instabile Fragmente aufgehoben werden, werden Heilung und Schaden gegen ' Verstärkter Panzer ' 30 Sek. lang um 50% erhöht. Dieser Effekt ist stapelbar.\n\nZusätzlich fügt ' Instabile Energie ' allen betroffenen Spielercharakteren alle 2 Sek. 363667 Schattenschaden zu." }
