entries[423582] = { ["name"] = "Entzündendes Inferno", ["text"] = "100 Meter Reichweite\nSofort\nLohenzar entfesselt eine feurige Explosion auf jede gelöschte Kerze, entzündet sie wieder und fügt allen dabei getroffenen Spielercharakteren 8487876 Feuerschaden zu.\n\nDas Inferno versengt alle Spielercharaktere und fügt ihnen so 8 Sek. lang alle 1 Sek. 242445 Feuerschaden zu. Dieser Effekt ist stapelbar." }
entries[423583] = { ["name"] = "Verdammnisbrand", ["text"] = "100 Meter Reichweite\nSofort\nWenn ein 'Dämonischer Kern' verschlungen wird, verursacht dies einen 'Verdammnisbrand', der nach 20 Sek. explodiert und Gegnern in der Nähe (268.747% der Zaubermacht) Schattenschaden oder einem einzigen Gegner [(268.747% der Zaubermacht) * 2.25] Schattenschaden zufügt. 'Hand von Gul'dan' verringert die Dauer Eurer aktiven Verdammnisbrände um 1 Sek. pro verbrauchtem Seelensplitter." }
entries[423584] = { ["name"] = "Verdammnisbrand", ["text"] = "100 Meter Reichweite\nSofort\nWenn ein 'Dämonischer Kern' verschlungen wird, verursacht dies einen 'Verdammnisbrand', der nach 20 Sek. explodiert und Gegnern in der Nähe (268.747% der Zaubermacht) Schattenschaden oder einem einzigen Gegner [(268.747% der Zaubermacht) * 2.25] Schattenschaden zufügt. 'Hand von Gul'dan' verringert die Dauer Eurer aktiven Verdammnisbrände um 1 Sek. pro verbrauchtem Seelensplitter." }
entries[423585] = { ["name"] = "Schreckensdämon", ["text"] = "100 Meter Reichweite\nSofort\nWenn 'Verdammnisbrand' entfernt wird, besteht eine Chance, einen Schreckensdämon zu beschwören, der 5-mal 'Verdammnisblitzsalve' wirkt, bevor er wieder verschwindet. Jede 'Verdammnisblitzsalve' fügt bis zu 4 Gegnern [(1.553369999\n* (Zaubermacht) * 1 * (1 + Vielseitigkeit)) * 1.169617819] Schattenschaden oder einem einzigen Gegner [((1.553369999\n* (Zaubermacht) * 1 * (1 + Vielseitigkeit)) * 1.169617819) * 2.1] Schattenschaden zu." }
entries[423587] = { ["name"] = "Teufelsblitz" }
entries[423588] = { ["name"] = "Lichtbarriere", ["text"] = "Sofort\nWenn Murrbet 50% Gesundheit erreicht, schützt sie sich mit einem Schild aus Licht, der 49812335 Schaden absorbiert und Immunität gegen Unterbrechungseffekte gewährt." }
entries[423590] = { ["name"] = "Echos des Zorns", ["text"] = "Sofort\n'Zornerfüllte Sanktion' gewährt Euch 'Echos des Zorns', wodurch Euer nächster Einsatz von 'Urteil des Templers' oder 'Göttlicher Sturm' ein zweites Mal mit 25% Effektivität Schaden verursacht. Dieser Effekt verbraucht kein 'Richturteil'.\n(100ms Abklingzeit)" }
entries[423591] = { ["name"] = "Sturm des Lichtbringers", ["text"] = "100 Meter Reichweite\nSofort\nDer Aschenbringer projiziert den Zauber 'Göttlicher Sturm' 20 Meter nach vorne und fügt allen Gegnern auf dem Weg Schaden zu.\n\nErhöht zusätzlich den von 'Göttlicher Sturm' verursachten Schaden um 33%." }
entries[423593] = { ["name"] = "Göttlicher Sturm", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt einen Wirbel göttlicher Energie, der allen Gegnern in der Nähe [ Brennender Kreuzzug : [(128.05% der Angriffskraft) * 1.05] Strahlenschaden / (128.05% der Angriffskraft) Heiligschaden] zufügt.\n\nFügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
entries[423598] = { ["name"] = "Lodernde Saat", ["text"] = "Sofort\nDie lodernde Saat pulsiert mit einer Flamme, die allen Spielercharakteren 6 Sek. lang alle 1 Sek. 1450473 Schattenflammenschaden zufügt." }
entries[423601] = { ["name"] = "Saat von Amirdrassil", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Amirdrassil zu blühen beginnt, bilden sich auf der Oberfläche Samen, die von Spielercharakteren getragen werden können.\n\nDie Samen entfalten in regelmäßigen Abständen ihre Kraft und ermöglichen Spielercharakteren, die sie tragen, den Start einer ' Blüte '.\n\nSaaten werden ' Lodernde Saat ', wenn sie von Schattenflamme direkt getroffen werden." }
