entries[423610] = { ["name"] = "Verzehrende Flamme", ["text"] = "Unbegrenzte Reichweite\nSofort\nNach 3 Einsätzen von 'Flammendes Inferno' schöpft Larodar 16 Sek. lang aus den Flammen in der Umgebung, fügt dabei allen Spielercharakteren alle 0.5 Sek. 116038 Feuerschaden zu und zieht diese zu sich. Zusätzlich fügt der Hüter Spielercharakteren innerhalb von 3 Metern 108785 Feuerschaden zu.\n\nLarodar geht dadurch in Flammen auf, wodurch er in den Avatar der Asche verwandelt wird." }
entries[423611] = { ["name"] = "Seelenzündung", ["text"] = "Sofort 2 min Abklingzeit\nEntzieht den Überresten der Glutseele Kraft, was die Hauptwert 20 Sek. lang um 312 erhöht. Der Effekt wird alle 2 Sek. schwächer. Sobald dieser Effekt endet, werdet Ihr 'Ausgebrannt' und verliert für 60 Sek. 57 Tempo, bevor Ihr Euch erholt.\n\nWenn die Lage kritisch wird, entzündet sich Eure Seele und gewährt Euch diesen Bonus erneut, ohne sich abzuschwächen. Dieser Effekt kann nur einmal pro Kampf auftreten." }
